class Counter : DbCommandInterceptor
{
    public int N;
    public override InterceptionResult<DbDataReader> ReaderExecuting(DbCommand c, CommandEventData e, InterceptionResult<DbDataReader> r) { N++; return r; }
    public override ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(DbCommand c, CommandEventData e, InterceptionResult<DbDataReader> r, CancellationToken ct = default) { N++; return new(r); }
}
class Db(Counter c) : DbContext
{
    public static readonly SqliteConnection Conn = Open();
    static SqliteConnection Open() { var c = new SqliteConnection("Data Source=:memory:"); c.Open(); return c; }
