#:package Microsoft.Extensions.Caching.Memory@10.0.0
using Microsoft.Extensions.Caching.Memory;

var cache = new MemoryCache(new MemoryCacheOptions());
var gate = new SemaphoreSlim(1, 1);
var dbCalls = 0;

async Task<string> GetAsync()
{
    if (cache.TryGetValue("featured", out string? v)) return v!;

    await gate.WaitAsync();
    try
    {
        dbCalls++;
        await Task.Delay(50);
        cache.Set("featured", "data");
        return "data";
    }
    finally { gate.Release(); }
}

await Task.WhenAll(Enumerable.Range(0, 5).Select(_ => GetAsync()));
Console.WriteLine(dbCalls);

